<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$p=db();$bq=$p->prepare('SELECT * FROM batches WHERE department_id=? ORDER BY batch_name');$bq->execute([$_SESSION['user']['department_id']]);$batches=$bq->fetchAll();$bid=(int)($_GET['batch_id']??($batches[0]['id']??0));$search=trim($_GET['q']??'');$q=$p->prepare('SELECT s.* FROM students s JOIN batches b ON b.id=s.batch_id WHERE s.batch_id=? AND b.department_id=? AND (s.registration_number LIKE ? OR s.student_name LIKE ?) ORDER BY s.registration_number');$q->execute([$bid,$_SESSION['user']['department_id'],"%$search%","%$search%"]);$title='Students';require __DIR__.'/../../includes/header.php';?><section class="panel"><form method="get" class="inline-form"><label>Batch<select name="batch_id" onchange="this.form.submit()"><?php foreach($batches as $b):?><option value="<?=$b['id']?>" <?=$bid===$b['id']?'selected':''?>><?=e($b['batch_name'])?></option><?php endforeach?></select></label><label>Search<input name="q" value="<?=e($search)?>"></label><button>Search</button></form></section><div class="panel table-wrap"><table><tr><th>Registration No.</th><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th></th></tr><?php foreach($q as $s):?><tr><td><?=e($s['registration_number'])?></td><td><?=e($s['student_name'])?></td><td><?=e($s['email'])?></td><td><?=e($s['phone'])?></td><td><?=e($s['status'])?></td><td><a class="button secondary" href="edit.php?id=<?=$s['id']?>">Edit</a></td></tr><?php endforeach?></table></div><?php require __DIR__.'/../../includes/footer.php';?>
